"""html_viewer: Generate a self-contained HTML subtitle editor/viewer.

Opens via file:// — no server required. Media is loaded via a file picker
using URL.createObjectURL() to work around browser cross-origin restrictions.
SRT data is embedded as JSON in a <script> tag.

CSS and JS are stored in html_viewer_template.py to keep this file concise.
"""
from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

from atcli.core.html_viewer_template import VIEWER_CSS, build_viewer_js


def _parse_srt(srt_path: str) -> list[dict[str, Any]]:
    """Parse an SRT file into subtitle dicts with start/end in milliseconds."""
    text = Path(srt_path).read_text(encoding="utf-8")
    blocks = re.split(r"\n\n+", text.strip())
    subtitles: list[dict[str, Any]] = []

    def _ts_to_ms(ts: str) -> int:
        ts = ts.replace(",", ".")
        h_str, m_str, rest = ts.split(":")
        s_str, mil_str = rest.split(".")
        return int(h_str) * 3_600_000 + int(m_str) * 60_000 + int(s_str) * 1_000 + int(mil_str)

    for block in blocks:
        lines = block.strip().splitlines()
        if len(lines) < 3:
            continue
        try:
            index = int(lines[0].strip())
            start_str, end_str = lines[1].strip().split(" --> ")
            sub_text = "\n".join(lines[2:]).strip()
            subtitles.append({
                "index": index,
                "start": _ts_to_ms(start_str),
                "end": _ts_to_ms(end_str),
                "text": sub_text,
            })
        except (ValueError, IndexError):
            continue

    return subtitles


_ICON_WAVE = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h2M6 8v8M10 5v14M14 9v6M18 6v12M22 12h-2"/></svg>'
_ICON_PLUS = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>'
_ICON_EXPORT = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>'
_ICON_UPLOAD = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>'
_ICON_FILM = '<svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="2" width="20" height="20" rx="2.18" ry="2.18"/><line x1="7" y1="2" x2="7" y2="22"/><line x1="17" y1="2" x2="17" y2="22"/><line x1="2" y1="12" x2="22" y2="12"/><line x1="2" y1="7" x2="7" y2="7"/><line x1="17" y1="7" x2="22" y2="7"/><line x1="17" y1="17" x2="22" y2="17"/><line x1="2" y1="17" x2="7" y2="17"/></svg>'


def _build_html(subtitles: list[dict[str, Any]], srt_filename: str) -> str:
    """Assemble the complete self-contained HTML document."""
    subs_json = json.dumps(subtitles, ensure_ascii=False)
    count = len(subtitles)
    last_end_ms = subtitles[-1]["end"] if subtitles else 0
    total_s = last_end_ms // 1000
    total_dur = f"{total_s // 3600:02d}:{(total_s % 3600) // 60:02d}:{total_s % 60:02d}"
    export_filename = srt_filename.replace(".srt", "_edited.srt")
    js = build_viewer_js(subs_json, export_filename)

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Subtitle Editor — {srt_filename}</title>
<style>{VIEWER_CSS}</style>
</head>
<body>
<header>
  <div class="hd-logo">
    {_ICON_WAVE}
    <span class="hd-title">Subtitle Editor</span>
  </div>
  <div class="hd-div"></div>
  <span class="hd-file" title="{srt_filename}">{srt_filename}</span>
  <div class="hd-right">
    <span class="badge">{count} cues</span>
    <span class="badge">{total_dur}</span>
    <div class="hd-div"></div>
    <button class="btn btn-outline" onclick="addRow()">{_ICON_PLUS} Add row</button>
    <button class="btn btn-ac" onclick="exportSRT()">{_ICON_EXPORT} Export SRT</button>
  </div>
</header>
<div class="main">
  <div class="sub-panel">
    <div class="toolbar">
      <span class="sub-count">{count} cues</span>
      <div class="toolbar-sep"></div>
      <span class="kbd">↑↓ navigate</span>
      <span class="kbd" style="margin-left:4px">⌘S export</span>
    </div>
    <div class="sub-wrap" id="sw">
      <table>
        <thead>
          <tr>
            <th style="width:40px">#</th>
            <th style="width:120px">Start</th>
            <th style="width:120px">End</th>
            <th>Subtitle</th>
            <th style="width:34px"></th>
          </tr>
        </thead>
        <tbody id="sb"></tbody>
      </table>
    </div>
  </div>
  <div class="media-panel">
    <div class="player-wrap" id="pw">
      <div class="ph">
        {_ICON_FILM}
        <p>No media loaded</p>
        <small>Load an audio or video file to start playback</small>
      </div>
      <div id="sub-overlay"></div>
    </div>
    <div class="file-bar">
      <label class="upload-btn" for="mf">{_ICON_UPLOAD} Load media</label>
      <input type="file" id="mf" accept="audio/*,video/*" onchange="loadMedia(this)">
      <span class="file-lbl">No file selected</span>
    </div>
  </div>
</div>
<script>{js}</script>
</body>
</html>"""


def generate_viewer(srt_path: str, media_path: str | None = None) -> str:  # noqa: ARG001
    """Generate a self-contained HTML viewer for the given SRT file.

    media_path is accepted for API compatibility but ignored — browsers cannot
    access arbitrary local files via file://; the viewer uses a file picker instead.

    Returns the absolute path to the generated HTML file.
    """
    srt = Path(srt_path)
    subtitles = _parse_srt(srt_path)
    html = _build_html(subtitles, srt.name)
    out_path = srt.parent / f"{srt.stem}_viewer.html"
    out_path.write_text(html, encoding="utf-8")
    return str(out_path)
